  function renderOriginPreview(preview){state.originPreview=preview;const ready=preview&&preview.read&&preview.write;$("originPreview").textContent=preview?preview.message:"Проверка не выполнена.";$("changeOrigin").disabled=!ready;return ready}
  async function loadRepository(){const message=$("repositoryMessage");message.textContent="Получение состояния origin…";$("pullRepository").disabled=true;$("pushRepository").disabled=true;$("pushDefaultRepository").disabled=true;try{const result=await api("/api/viewer/repository?conversation="+encodeURIComponent(state.conversation),{timeoutMs:65000});renderRepository(result.repository,result.connection,result.experience,result.activeRun);return result}catch(error){message.textContent=error.message;$("repositoryBadge").textContent="ошибка";$("repositoryBadge").className="repository-badge error";return null}}
