  async function connectRepository(withRemote){const button=withRemote?$("connectRepository"):$("createRepositoryKey");const remoteUrl=withRemote?$("repositoryUrl").value.trim():"";if(withRemote&&!remoteUrl){toast("Укажите SSH URL репозитория");return}button.disabled=true;try{await postRepository("connect",{remoteUrl});$("repositoryUrl").value="";await loadSession();toast("Deploy key создан — добавьте публичный ключ в Git-сервис")}catch(error){toast(error.message);await loadRepository()}}
