  async function copyFrom(id,label){const field=$(id),value=field.value;if(!value)return;try{if(navigator.clipboard&&navigator.clipboard.writeText)await navigator.clipboard.writeText(value);else{field.select();document.execCommand("copy")}toast(label+" скопирован")}catch{toast("Не удалось скопировать ключ")}}
  async function migrateLegacy(){if(!confirm("Проверить управляемый ключ и удалить только project-local core.sshCommand?"))return;try{await postRepository("migrate-legacy");toast("Старая SSH-настройка удалена")}catch(error){toast(error.message);await loadRepository()}}
